/* @autogenerated */
import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { TranslocoPipe } from '@jsverse/transloco';
import { AppStateService } from '@shared/context/state/app-state.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AuthorizationAccessService } from './authorization-access.service';
import { UnauthorizedReason } from './guards/is-authenticated.guards';
import { ErrorPageComponent } from '@shared/toolkit/error-page/error-page.component';

@Component({
  selector: 'unauthorized-page',
  standalone: true,
  imports: [ErrorPageComponent, MatButtonModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <app-page-error
      [error]="error"
      [titleKey]="'auth.unauthorized.' + reason + '.title'"
      [messageKey]="'auth.unauthorized.' + reason + '.message'"
      [showHome]="reason === '403'"
    >
      @if (reason === '401') {
        <button mat-flat-button (click)="login()">{{ 'auth.unauthorized.login' | transloco }}</button>
      } @else {
        <button mat-button (click)="switchAccount()">{{ 'auth.unauthorized.switchAccount' | transloco }}</button>
      }
    </app-page-error>
  `,
})
export class UnauthorizedComponent {
  private readonly router = inject(Router);
  private readonly state = inject(AppStateService);
  private readonly identity = inject(IdentityService);
  private readonly access = inject(AuthorizationAccessService);

  readonly reason: UnauthorizedReason;
  /** Para la imagen de ErrorPageComponent (`error-401.png` / `error-403.png`). */
  readonly error: { status: number };
  private readonly returnUrl: string | null;
  private readonly currentLanguage = this.state.language;
  private readonly currentTenant = this.state.tenant;

  constructor() {
    const params = inject(ActivatedRoute).snapshot.queryParamMap;
    this.reason = params.get('reason') === '403' ? '403' : '401';
    this.error = { status: Number(this.reason) };
    this.returnUrl = params.get('returnUrl');

    // Con 403 el usuario ya está autenticado: volver a returnUrl lo devolvería aquí en bucle
    if (this.reason === '401') {
      this.state
        .user$('main')
        .pipe(takeUntilDestroyed())
        .subscribe((user) => {
          if (user.authenticated) {
            this.returnUrl ? this.router.navigateByUrl(this.returnUrl) : this.home();
          }
        });
    }
  }

  login(): void {
    // El guard canceló la navegación, así que la ruta pedida no se ha guardado: tras el login se vuelve a ella
    if (this.returnUrl) {
      this.access.remember(this.returnUrl);
    }
    this.identity.login('main');
  }

  home(): void {
    this.router.navigate([this.currentLanguage(), this.currentTenant()]);
  }

  switchAccount(): void {
    this.identity.logout('main');
  }
}
